    params: [{ id: 'L', label: T('String length L', 'طول الخيط L'), min: 0.3, max: 2.6, step: 0.05, val: 1.6, d: 2, unit: ' m' }, { id: 'deg', label: T('Angle from vertical θ', 'الزاوية عن الرأسي θ'), min: 5, max: 80, step: 0.5, val: 35, d: 1, unit: '°', show: p => p.mode === 'angle' }, { id: 'w', label: T('Angular speed ω', 'السرعة الزاوية ω'), min: 0.5, max: 12, step: 0.05, val: 3.2, d: 2, unit: ' rad/s', show: p => p.mode === 'omega' }, { id: 'm', label: T('Bob mass m', 'كتلة الثقل m'), min: 0.1, max: 5, step: 0.1, val: 1, d: 1, unit: ' kg' }],
    preset: { mode: 'angle', L: 1.6, deg: 35, m: 1 },
