      const top = M.rbox(3.1, 0.1, 3.1, 0.04, dark); top.position.y = 3.2; S.scene.add(top); const hub = M.cyl(0.08, 0.05, 0.12, steel, 24); hub.position.y = 3.12; S.scene.add(hub);
      W.str = M.link(0.008, M.mat(0xf2efe6, { roughness: 0.7 })); S.scene.add(W.str);
      W.bob = M.ball(0.11, M.mat(0xffb648, { metalness: 0.85, roughness: 0.18, clearcoat: 1 })); S.scene.add(W.bob);
