    rebuildOn: ['R'], preset: { surf: 'smooth', R: 1.2, th0: 1, v0: 0 },
    init: p => E.sphereInit(p.R, p.v0, p.th0 * D2R),
    step(s, p, h) { E.sphereStep(s, { R: p.R, mu: p.surf === 'rough' ? p.mu : 0 }, h); if (s.ph === 'landed') return false; },
    done: s => s.ph === 'landed' || (s.stuck && s.t > 0.5), phase: s => s.ph, fx: { air: 0x6ff3ff, landed: 0xffc247 },
    pos(s, p) { return s.ph === 'on' ? [p.R * Math.sin(s.th), p.R + p.R * Math.cos(s.th), 0] : [s.x, s.y, 0]; },
