    status: (s, p) => (s.ph !== 'on' ? { k: 'warn', t: p.kind === 'track' ? T('Contact lost — falling', 'فقد التلامس') : T('String slack — projectile', 'الخيط مرتخٍ') } : s.T < 0 ? { k: 'ok', t: T('Rod in compression', 'القضيب منضغط') } : { k: 'ok', t: p.kind === 'track' ? T('On the track', 'على المسار') : T('String taut', 'الخيط مشدود') }),
    graph: { title: T('Tension (or N) and speed against time', 'الشد والسرعة مع الزمن'), xl: 't (s)', yl: 'T / mg · v (m/s)', series: [{ label: 'T / mg' }, { label: 'v (m/s)' }], sample: (s, p, t) => [t, s.ph === 'on' ? s.T / g : 0, s.ph === 'on' ? Math.abs(p.R * s.phid) : Math.hypot(s.vx, s.vy)], xr: (p, h) => { const t1 = h.length ? h[h.length - 1][0] : 0; return [Math.max(0, t1 - 6), Math.max(6, t1)]; }, yr: p => [-2, Math.max(8, p.v0 * 1.1, (p.v0 * p.v0 / p.R + g) / g * 1.1)] },
    invest: [{ t: T('String, v₀ below √(2gR): the ball only swings — never above the horizontal.', 'تحت √(2gR).'), done: (s, p) => p.kind === 'string' && p.v0 < Math.sqrt(2 * g * p.R) && s.t > 1.5 && s.lost == null }, { t: T('String, √(2gR) < v₀ < √(5gR): the string goes slack.', 'بين الحدين.'), done: (s, p) => p.kind === 'string' && s.lost != null }, { t: T('Press **Set v₀ to the minimum**: the ball just completes the loop.', 'اضبط الحد الأدنى.'), done: (s, p) => p.kind !== 'rod' && s.laps >= 1 && p.v0 < E.vcMin(p.R, 'string') * 1.02 }, { t: T('Rod with v₀ between √(4gR) and √(5gR): it loops — with the rod pushing at the top.', 'القضيب.'), done: (s, p) => p.kind === 'rod' && s.laps >= 1 && s.minT < 0 }],
    challenge: { make(rnd) { const R = +(0.6 + rnd() * 1.3).toFixed(2); return { p: { kind: 'string', R, v0: 2 }, after: { v0: +Math.min(14, Math.sqrt(5 * g * R) * 1.003).toFixed(2) }, q: T(`A ball on a string of length <b>${R} m</b> is whirled in a vertical circle. What is the smallest speed at the bottom that keeps the string taut all the way round?`, 'ما أدنى سرعة؟'), ans: Math.sqrt(5 * g * R), unit: 'm/s', explain: 'v_top² ≥ gR and energy ⇒ v₀ ≥ √(5gR). The lab then runs at that speed.' }; } },
