  const TH = 0.78, RT = 0.5; // table top height, table radius
  reg('cm-table', {
    intro: 'A coin sits on a turntable. Static friction carries it round — friction is the centripetal force. Spin faster and the friction needed, m ω² r, grows until it exceeds the most static friction can give, μ<sub>s</sub>mg. Then the coin **slips**: from that moment kinetic friction acts against its motion relative to the table, it spirals outwards and flies off the edge.',
    predict: { q: 'Two identical coins sit on a turntable that slowly speeds up; one is twice as far from the centre. Which slips first?', options: ['the inner coin', 'the outer coin', 'both together', 'neither ever slips'] },
    explore: '- **Spin up** slowly and note ω when the coin slips; compare with √(μg/r).\n- Move the coin inwards and repeat.\n- Change the coin’s mass.\n- Constant ω above the limit: it slips at once.',
    explain: 'While the coin moves with the table, static friction is the **only horizontal force**, and it must equal m ω² r (plus m α r along the rim while the table speeds up). It can be at most **μ<sub>s</sub> m g**, so the coin slips when **ω² r > μ<sub>s</sub> g**, i.e. **ω > √(μ<sub>s</sub> g / r)** — the mass cancels. The farther out, the smaller the limiting ω. Once it slips, the coin is no longer in circular motion with the table: kinetic friction μ<sub>k</sub>mg opposes its velocity relative to the table, it spirals out and leaves the edge as a projectile.',
    apply: [q('cm8-a', 'A coin 0.2 m from the centre of a turntable with μs = 0.4 slips above ω ≈', ['2.0 rad/s', '4.4 rad/s', '7.0 rad/s', '19.6 rad/s'], 1, '√(0.4 × 9.81/0.2) = 4.43 rad/s.'), q('cm8-b', 'Doubling the coin’s mass makes the slipping ω…', ['larger', 'smaller', 'the same', 'zero'], 2, 'm cancels.'), q('cm8-c', 'What provides the centripetal force on the coin before it slips?', ['the normal force', 'static friction', 'gravity', 'the centrifugal force'], 1, 'Friction is the only horizontal force.'), q('cm8-d', 'After slipping, the coin…', ['keeps moving in its circle', 'moves outwards along a spiral then leaves tangentially', 'moves straight to the centre', 'stops at once'], 1, 'Kinetic friction can no longer supply m ω² r.')],
    summary: ['Static friction supplies m ω² r (and m α r while speeding up).', 'Slips when ω > √(μs g / r): mass cancels; outer objects slip first.', 'After slipping: kinetic friction opposes relative motion; the object spirals out.'],
    connect: [{ label: 'Platform with several masses', href: '#/exp/cm-multi' }, { label: 'Car on a flat curve', href: '#/exp/cm-flat' }],
    preset: true
  }, () => ({ id: 'cm-table', title: T('Mass on a rotating table', 'جسم على طاولة دوّارة'), h: 1 / 480, labelH: 0.1, flen: 0.32, fmax: 1.1, arrowR: 0.012, trailStep: 0.01, trailCol: 0xffd76a,
    scene: { cam: [0.9, 1.55, 1.25], target: [0, 0.72, 0], fog: [0x0b1020, 8, 30], minDist: 0.4 },
    modes: [{ id: 'drive', label: T('Table', 'الطاولة'), opts: [['ramp', T('Spin up slowly (α)', 'تسارع تدريجي')], ['const', T('Constant ω', 'ω ثابتة')]], val: 'ramp' }],
    params: [{ id: 'rc', label: T('Coin distance r', 'بعد العملة r'), min: 0.05, max: 0.45, step: 0.01, val: 0.3, d: 2, unit: ' m' }, { id: 'w', label: T('Angular speed ω', 'السرعة الزاوية ω'), min: 0.5, max: 12, step: 0.05, val: 4, d: 2, unit: ' rad/s', show: p => p.drive === 'const' }, { id: 'al', label: T('Angular acceleration α', 'التسارع الزاوي α'), min: 0.05, max: 1.5, step: 0.05, val: 0.3, d: 2, unit: ' rad/s²', show: p => p.drive === 'ramp' }, { id: 'mus', label: T('Static friction μs', 'الاحتكاك السكوني μs'), min: 0.05, max: 1, step: 0.01, val: 0.4, d: 2 }, { id: 'muk', label: T('Kinetic friction μk', 'الاحتكاك الحركي μk'), min: 0.02, max: 1, step: 0.01, val: 0.3, d: 2 }, { id: 'm', label: T('Coin mass m', 'الكتلة m'), min: 0.005, max: 0.2, step: 0.005, val: 0.02, d: 3, unit: ' kg' }],
    preset: { drive: 'ramp', rc: 0.3, al: 0.3, mus: 0.4, muk: 0.3 },
    onParam(id, v, s, p, lab) { if (id === 'muk' && v > p.mus) lab.set('muk', p.mus); if (id === 'mus' && p.muk > v) lab.set('muk', v); },
    init: p => E.tableInit([{ r: p.rc, mus: p.mus, muk: Math.min(p.muk, p.mus), m: p.m }], p.drive === 'const' ? p.w : 0),
    P: p => ({ Rt: RT, H: TH, al: p.drive === 'ramp' ? p.al : 0, wmax: p.drive === 'ramp' ? 14 : p.w }),
    step(s, p, h) { E.tableStep(s, this.P(p), h); const c0 = s.coins[0]; if (c0.ph === 'floor' && Math.hypot(c0.vx, c0.vz) < 1e-3) return false; },
    done: s => s.coins[0].ph === 'floor' && Math.hypot(s.coins[0].vx, s.coins[0].vz) < 1e-3, phase: s => (s.coins[0].stuck ? 'grip' : s.coins[0].ph === 'table' ? 'slip' : s.coins[0].ph), fx: { slip: 0xffb648, air: 0x6ff3ff, floor: 0xffc247 },
    focus(s) { const c0 = s.coins[0]; return [c0.x, TH + 0.006 + c0.y, c0.z]; }, vel: s => [s.coins[0].vx, s.coins[0].vy, s.coins[0].vz], vscale: () => 0.08,
    forces(s, p) { const c0 = s.coins[0], al = this.P(p).al, w = s.w, L = [{ k: 'mg', v: [0, -p.m * g, 0], label: 'mg' }]; if (c0.ph === 'table') { L.push({ k: 'N', v: [0, p.m * g, 0], label: 'N' }); let F;
        if (c0.stuck) { const u = inw(c0.x, c0.z), r0 = Math.hypot(c0.x, c0.z) || 1, td = [c0.z / r0, 0, -c0.x / r0]; F = [p.m * (w * w * c0.r * u[0] + al * c0.r * td[0]), 0, p.m * (w * w * c0.r * u[2] + al * c0.r * td[2])]; } else { const sx = w * c0.z, sz = -w * c0.x, rx = c0.vx - sx, rz = c0.vz - sz, rv = Math.hypot(rx, rz) || 1; F = [-rx / rv * c0.muk * p.m * g, 0, -rz / rv * c0.muk * p.m * g]; }
        L.push({ k: 'f', v: F, label: c0.stuck ? T('static friction', 'احتكاك سكوني') : T('kinetic friction', 'احتكاك حركي') }); } if (c0.ph === 'floor') L.push({ k: 'N', v: [0, p.m * g, 0], label: 'N' }); return L; },
    basis(s) { const c0 = s.coins[0], r = Math.hypot(c0.x, c0.z) || 1; return { x: [-c0.x / r, 0, -c0.z / r], y: [0, 1, 0] }; }, fscale: p => 1 / (p.m * g), netLabel: () => T('net force', 'المحصلة'),
    build({ THREE, S, M }) { const W = {}; W.tab = new THREE.Group(); S.scene.add(W.tab);
      const ttex = LS.circArt.tex(THREE, 512, 512, (gx, w, h) => { const gr = gx.createRadialGradient(256, 256, 10, 256, 256, 256); gr.addColorStop(0, '#2b3a5c'); gr.addColorStop(1, '#16203a'); gx.fillStyle = gr; gx.fillRect(0, 0, w, h); gx.strokeStyle = 'rgba(160,190,255,.35)'; gx.lineWidth = 2; for (let r = 40; r < 256; r += 40) { gx.beginPath(); gx.arc(256, 256, r, 0, 7); gx.stroke(); } for (let i = 0; i < 24; i++) { gx.strokeStyle = i % 6 ? 'rgba(160,190,255,.18)' : 'rgba(255,210,120,.7)'; gx.lineWidth = i % 6 ? 1.5 : 3; gx.beginPath(); gx.moveTo(256, 256); gx.lineTo(256 + 250 * Math.cos(i / 24 * TAU), 256 + 250 * Math.sin(i / 24 * TAU)); gx.stroke(); } });
      const top = new THREE.Mesh(new THREE.CylinderGeometry(RT, RT, 0.03, 96), [M.mat(0x8fa0bd, { metalness: 0.9, roughness: 0.25 }), new THREE.MeshPhysicalMaterial({ map: ttex, roughness: 0.55, clearcoat: 0.4 }), M.mat(0x8fa0bd)]); top.position.y = TH - 0.015; top.castShadow = top.receiveShadow = true; W.tab.add(top);
      const shaft = M.cyl(0.035, 0.035, TH - 0.18, M.mat(0xc2cbd8, { metalness: 0.95, roughness: 0.2 }), 24); shaft.position.y = (TH - 0.18) / 2 + 0.12; S.scene.add(shaft); const base = M.cyl(0.26, 0.3, 0.12, M.mat(0x22293a, { metalness: 0.6 }), 48); base.position.y = 0.06; S.scene.add(base);
      W.coin = M.cyl(0.022, 0.022, 0.006, M.mat(0xe7b74a, { metalness: 1, roughness: 0.22 }), 40); S.scene.add(W.coin);
      W.lim = new THREE.Mesh(new THREE.TorusGeometry(1, 0.0025, 6, 160), new THREE.MeshBasicMaterial({ color: 0xff6fae, transparent: true, opacity: 0.8 })); W.lim.rotation.x = PI / 2; W.lim.position.y = TH + 0.002; S.scene.add(W.lim); return W; },
    pose(W, s, p) { W.tab.rotation.y = s.Th; const fp = this.focus(s); W.coin.position.set(fp[0], fp[1], fp[2]); const w = Math.max(0.05, s.w), rl = Math.min(RT, p.mus * g / (w * w)); W.lim.scale.set(rl, rl, 1); W.lim.visible = s.w > 0.05; },
    read(s, p) { const c0 = s.coins[0], al = this.P(p).al, wl = E.tableSlipW(p.rc, p.mus), need = p.m * Math.sqrt((s.w * s.w * c0.r) ** 2 + (al * c0.r) ** 2); return [[T('table ω', 'ω الطاولة'), f(s.w, 3) + ' rad/s'], [T('slip limit √(μs g/r)', 'حد الانزلاق'), f(wl, 3) + ' rad/s'], [T('friction needed', 'الاحتكاك المطلوب'), c0.stuck ? f(need, 4) + ' N' : '—'], [T('max static friction μs mg', 'أقصى احتكاك'), f(p.mus * p.m * g, 4) + ' N'], [T('state', 'الحالة'), c0.stuck ? T('moving with the table', 'يتحرك مع الطاولة') : c0.ph === 'table' ? T('slipping', 'ينزلق') : c0.ph === 'air' ? T('falling', 'يسقط') : T('on the floor', 'على الأرض')], [T('slipped at ω', 'انزلق عند'), c0.slipW != null ? f(c0.slipW, 3) + ' rad/s (t = ' + f(c0.slipT, 2) + ' s)' : '—'], [T('distance from axis', 'البعد'), f(Math.hypot(c0.x, c0.z), 3) + ' m']]; },
    formulas(s, p) { const c0 = s.coins[0], al = this.P(p).al; return [`f<sub>needed</sub> = m√((ω²r)² + (αr)²) = ${f(p.m, 3)} × √((${f(s.w, 2)}² × ${f(p.rc)})² + (${f(al, 2)} × ${f(p.rc)})²) = ${B(f(p.m * Math.sqrt((s.w * s.w * p.rc) ** 2 + (al * p.rc) ** 2), 4) + ' N')}`, `f<sub>max</sub> = μs m g = ${f(p.mus)} × ${f(p.m, 3)} × 9.81 = ${B(f(p.mus * p.m * g, 4) + ' N')}`, `${T('slips when', 'ينزلق عندما')} ω > √(μs g / r) = √(${f(p.mus)} × 9.81 / ${f(p.rc)}) = ${B(f(E.tableSlipW(p.rc, p.mus), 3) + ' rad/s')}${al ? ' (' + T('with α: ω⁴ = (μs g/r)² − α²', 'مع α') + ')' : ''}`, c0.stuck ? '' : `${T('sliding', 'ينزلق')}: f<sub>k</sub> = μk m g = ${B(f(c0.muk * p.m * g, 4) + ' N')} ${T('against motion relative to the table', 'عكس الحركة النسبية')}`].filter(Boolean); },
    why: s => (s.coins[0].stuck ? T('Static friction is the **only horizontal force**, and it supplies exactly m ω² r (plus m α r along the rim while speeding up). The pink circle shows how far out the coin could grip at this ω.', 'الاحتكاك السكوني هو القوة المركزية.') : s.coins[0].ph === 'table' ? T('**Slipping**: m ω² r is more than μs m g. Kinetic friction now opposes the coin’s motion *relative to the table*; it can’t keep the coin on its circle, so it spirals outwards.', 'انزلاق.') : T('The coin left the table and is a projectile.', 'غادر الطاولة.')),
    status: s => (s.coins[0].stuck ? { k: 'ok', t: T('Gripping — static friction', 'متماسك') } : s.coins[0].ph === 'table' ? { k: 'warn', t: T('Slipping!', 'انزلاق!') } : s.coins[0].ph === 'air' ? { k: 'bad', t: T('Off the edge', 'خارج الحافة') } : { k: 'bad', t: T('On the floor', 'على الأرض') }),
    graph: { title: T('Friction needed vs available', 'الاحتكاك المطلوب والمتاح'), xl: 't (s)', yl: 'N', dec: 3, series: [{ label: T('needed m√((ω²r)²+(αr)²)', 'المطلوب') }, { label: 'μs m g' }], sample(s, p, t) { const c0 = s.coins[0], al = p.drive === 'ramp' ? p.al : 0; return [t, c0.stuck ? p.m * Math.sqrt((s.w * s.w * c0.r) ** 2 + (al * c0.r) ** 2) : NaN, p.mus * p.m * g]; }, yr: p => [0, p.mus * p.m * g * 1.6] },
    invest: [{ t: T('**Spin up** and let the coin slip. Compare the slip ω with √(μs g/r).', 'دوّر حتى الانزلاق.'), done: (s, p) => p.drive === 'ramp' && s.coins[0].slipW != null }, { t: T('Move the coin in to 0.12 m or less and repeat — it lasts longer.', 'قرّب العملة.'), done: (s, p) => p.rc <= 0.12 && s.coins[0].slipW != null }, { t: T('Change the mass and repeat — the slip ω is the same.', 'غيّر الكتلة.'), done: (s, p) => Math.abs(p.m - 0.02) > 0.01 && s.coins[0].slipW != null }, { t: T('Constant ω above the limit: it slips immediately.', 'ω ثابتة فوق الحد.'), done: (s, p) => p.drive === 'const' && s.coins[0].slipW != null }],
    challenge: { make(rnd) { const rc = +(0.1 + rnd() * 0.33).toFixed(2), mus = +(0.2 + rnd() * 0.6).toFixed(2), al = 0.2; return { p: { drive: 'ramp', rc, mus, muk: Math.min(0.3, mus), al }, q: T(`A coin sits <b>${rc} m</b> from the axis of a turntable (μs = <b>${mus}</b>). The table speeds up slowly (α = ${al} rad/s²). At what ω does the coin start to slip?`, 'عند أي ω ينزلق؟'), ans: Math.pow(Math.pow(mus * g / rc, 2) - al * al, 0.25), unit: 'rad/s', tol: 0.04, explain: 'ω ≈ √(μs g / r); the small α term (ω⁴ = (μs g/r)² − α²) changes it by much less than 1%.' }; } },
    observe(s, p) { const c0 = s.coins[0]; return { text: c0.slipW != null ? `The coin at r = ${f(p.rc)} m slipped at ω = ${f(c0.slipW, 2)} rad/s (√(μs g/r) = ${f(E.tableSlipW(p.rc, p.mus), 2)}).` : `The coin grips at ω = ${f(s.w, 2)} rad/s (limit ${f(E.tableSlipW(p.rc, p.mus), 2)} rad/s).`, predOk: i => i === 1 }; },
    state: s => ({ w: s.w, stuck: s.coins[0].stuck, ph: s.coins[0].ph, slipW: s.coins[0].slipW, r: Math.hypot(s.coins[0].x, s.coins[0].z) })
  }));
